import { Metadata } from 'next';
import { getTranslations } from 'next-intl/server';
import { useTranslations } from 'next-intl';
import { Link } from 'modules/i18n/utils/navigation';
import { cn } from 'lib/utils';

interface Props {
  params: Promise<{ lang: string }>;
}

export async function generateMetadata(props: Props): Promise<Metadata> {
  const { lang } = await props.params;
  const t = await getTranslations({ locale: lang, namespace: 'Team' });
  return { title: t('seoTitle'), description: t('seoDescription') };
}

type PortraitVariant = 'default' | 'blue' | 'green' | 'dark';

const portraitBg: Record<PortraitVariant, string> = {
  default: 'linear-gradient(180deg, #DCE1DB 0%, #B6BCB4 100%)',
  blue: 'linear-gradient(180deg, oklch(0.78 0.05 235), oklch(0.52 0.11 235))',
  green: 'linear-gradient(180deg, oklch(0.78 0.07 155), oklch(0.5 0.12 155))',
  dark: 'linear-gradient(180deg, #2B2F2D, #14171A)',
};

const cornerColor: Record<PortraitVariant, string> = {
  default: 'text-ink/60',
  blue: 'text-white/80',
  green: 'text-white/80',
  dark: 'text-white/80',
};

function PersonCard({
  idx,
  name,
  role,
  bio,
  variant = 'default',
}: {
  idx: string;
  name: string;
  role: string;
  bio: string;
  variant?: PortraitVariant;
}) {
  return (
    <div className="grid gap-3.5">
      <div
        className="aspect-3/4 relative overflow-hidden rounded-sm before:content-[''] before:absolute before:inset-0 before:bg-[repeating-linear-gradient(135deg,rgba(0,0,0,0.03)_0_1px,transparent_1px_9px)] after:content-[''] after:absolute after:inset-[auto_20%_0_20%] after:h-[55%] after:bg-[linear-gradient(180deg,rgba(13,15,14,0.1),rgba(13,15,14,0.4))] after:rounded-[50%_50%_0_0/40%_40%_0_0]"
        style={{ background: portraitBg[variant] }}>
        <span
          className={cn(
            'absolute top-3.5 left-3.5 font-mono text-[10px] tracking-[0.08em]',
            cornerColor[variant],
          )}>
          {idx} / 08
        </span>
      </div>
      <div>
        <div className="text-[18px] font-medium tracking-[-0.01em]">{name}</div>
        <div className="font-mono text-[11px] tracking-[0.08em] uppercase text-ink-3 mt-1">
          {role}
        </div>
      </div>
      <div className="text-[13px] text-ink-3 leading-normal border-t border-rule pt-2.5 mt-1">
        {bio}
      </div>
    </div>
  );
}

const Arrow = () => (
  <span className="inline-block w-14 h-px bg-current relative after:content-[''] after:absolute after:right-0 after:-top-3 after:w-7 after:h-7 after:border-r after:border-t after:border-current after:rotate-45" />
);

const GreenDot = () => (
  <span className="inline-block w-1.5 h-1.5 rounded-full bg-green mr-2.5 -translate-y-px" />
);

export default function TeamPage() {
  const t = useTranslations('Team');

  return (
    <main>
      <section className="max-w-[1440px] mx-auto px-[clamp(20px,4vw,64px)] pt-[clamp(80px,10vw,140px)] pb-[clamp(48px,6vw,80px)] border-b border-rule">
        <div className="font-mono text-[11px] tracking-[0.08em] uppercase text-ink-3 mb-5 flex gap-2.5 items-center">
          <Link href="/">Hidroing</Link>
          <span className="opacity-50">/</span>
          <span>{t('crumb')}</span>
        </div>
        <h1 className="font-medium tracking-[-0.025em] leading-[1.02] text-[clamp(40px,5.4vw,88px)] text-balance m-0">
          {t('title')}
        </h1>
        <div className="grid grid-cols-2 gap-20 mt-10 items-end max-md:grid-cols-[1fr] max-md:gap-6">
          <p className="text-[clamp(18px,1.4vw,22px)] leading-normal tracking-[-0.005em] text-ink-2 text-pretty max-w-[52ch]">
            {t('desc')}
          </p>
          <div className="grid gap-3.5">
            {[
              { label: t('statStaff'), value: '8' },
              { label: t('statChartered'), value: '6' },
              { label: t('statTenure'), value: '17' },
            ].map((stat) => (
              <div
                key={stat.label}
                className="flex justify-between border-t border-rule pt-2.5">
                <span className="font-mono text-[11px] tracking-widest uppercase text-ink-3 font-medium">
                  {stat.label}
                </span>
                <span className="font-mono [font-variant-numeric:tabular-nums] font-medium text-[18px]">
                  {stat.value}
                </span>
              </div>
            ))}
          </div>
        </div>
      </section>

      <section className="max-w-[1440px] mx-auto px-[clamp(20px,4vw,64px)] py-[clamp(56px,9vw,140px)]">
        {/* Department 1 */}
        <div className="flex gap-6 items-baseline mt-72 mb-7 border-t border-rule pt-7 first:mt-0">
          <div className="font-mono text-[12px] text-ink-4 tracking-[0.08em]">
            01
          </div>
          <h2 className="text-[clamp(24px,2.6vw,36px)] font-medium tracking-[-0.02em] m-0">
            {t('dept1Title')}
          </h2>
          <div className="ml-auto font-mono text-[11px] tracking-[0.08em] text-ink-3 uppercase">
            {t('dept1Count')}
          </div>
        </div>
        <div className="grid grid-cols-4 gap-8 gap-y-6 max-xl:grid-cols-3 max-md:grid-cols-2">
          <PersonCard
            idx="01"
            name={t('m1Name')}
            role={t('m1Role')}
            bio={t('m1Bio')}
            variant="blue"
          />
          <PersonCard
            idx="02"
            name={t('m2Name')}
            role={t('m2Role')}
            bio={t('m2Bio')}
            variant="green"
          />
          <PersonCard
            idx="03"
            name={t('m3Name')}
            role={t('m3Role')}
            bio={t('m3Bio')}
          />
          <PersonCard
            idx="04"
            name={t('m4Name')}
            role={t('m4Role')}
            bio={t('m4Bio')}
            variant="dark"
          />
        </div>

        {/* Department 2 */}
        <div className="flex gap-6 items-baseline mt-72 mb-7 border-t border-rule pt-7">
          <div className="font-mono text-[12px] text-ink-4 tracking-[0.08em]">
            02
          </div>
          <h2 className="text-[clamp(24px,2.6vw,36px)] font-medium tracking-[-0.02em] m-0">
            {t('dept2Title')}
          </h2>
          <div className="ml-auto font-mono text-[11px] tracking-[0.08em] text-ink-3 uppercase">
            {t('dept2Count')}
          </div>
        </div>
        <div className="grid grid-cols-4 gap-8 gap-y-6 max-xl:grid-cols-3 max-md:grid-cols-2">
          <PersonCard
            idx="05"
            name={t('m5Name')}
            role={t('m5Role')}
            bio={t('m5Bio')}
          />
          <PersonCard
            idx="06"
            name={t('m6Name')}
            role={t('m6Role')}
            bio={t('m6Bio')}
            variant="blue"
          />
          <PersonCard
            idx="07"
            name={t('m7Name')}
            role={t('m7Role')}
            bio={t('m7Bio')}
            variant="green"
          />
          <PersonCard
            idx="08"
            name={t('m8Name')}
            role={t('m8Role')}
            bio={t('m8Bio')}
            variant="dark"
          />
        </div>

        {/* Join card */}
        <div className="mt-20 p-12 border border-rule rounded-[4px] bg-white grid grid-cols-[2fr_1fr] gap-8 items-center max-md:grid-cols-[1fr] max-md:p-8">
          <div>
            <div className="font-mono text-[11px] tracking-widest uppercase text-ink-3 font-medium mb-3.5 flex items-center">
              <GreenDot />
              <span>{t('joinEyebrow')}</span>
            </div>
            <h3 className="font-medium tracking-[-0.02em] leading-[1.05] text-[clamp(28px,3.2vw,48px)] text-balance m-0">
              {t('joinTitle')}
            </h3>
            <p className="text-base leading-[1.6] text-ink-2 text-pretty mt-3 max-w-[52ch]">
              {t('joinDesc')}
            </p>
          </div>
          <div className="text-right">
            <a
              href="mailto:info@hidroing.hr"
              className="inline-flex items-center gap-2.5 px-[22px] py-3.5 rounded-full font-sans font-medium text-[14px] tracking-[-0.01em] border border-ink bg-ink text-paper cursor-pointer transition-all duration-150 hover:bg-green-ink hover:border-green-ink">
              {t('joinCta')} <Arrow />
            </a>
          </div>
        </div>
      </section>
    </main>
  );
}

'use client';

import { useTranslations } from 'next-intl';
import { Link } from 'modules/i18n/utils/navigation';
import { Placeholder } from '@modules/shared/components/Placeholder';
import { FormEvent } from 'react';

const Arrow = () => (
  <span className="inline-block w-14 h-px bg-current relative after:content-[''] after:absolute after:right-0 after:-top-3 after:w-7 after:h-7 after:border-r after:border-t after:border-current after:rotate-45" />
);

const GreenDot = () => (
  <span className="inline-block w-1.5 h-1.5 rounded-full bg-green mr-2.5 -translate-y-px" />
);

export default function ContactPage() {
  const t = useTranslations('Contact');

  function handleSubmit(e: FormEvent) {
    e.preventDefault();
    alert('Demo — hvala!');
  }

  const infoBlocks = [
    { label: t('officeLabel'), value: t('officeValue') },
    {
      label: t('phoneLabel'),
      value: '+385 31 200 200',
      href: 'tel:+38531200200',
    },
    {
      label: t('emailLabel'),
      value: 'info@hidroing.hr',
      href: 'mailto:info@hidroing.hr',
    },
    { label: t('hoursLabel'), value: t('hoursValue') },
    { label: t('vatLabel'), value: 'OIB 12345678901\nMBS 030012345' },
  ];

  const scopes = [
    t('scope1'),
    t('scope2'),
    t('scope3'),
    t('scope4'),
    t('scope5'),
    t('scope6'),
    t('scope7'),
    t('scope8'),
  ];

  return (
    <main>
      <section className="max-w-[1440px] mx-auto px-[clamp(20px,4vw,64px)] pt-[clamp(80px,10vw,140px)] pb-[clamp(48px,6vw,80px)] border-b border-rule">
        <div className="font-mono text-[11px] tracking-[0.08em] uppercase text-ink-3 mb-5 flex gap-2.5 items-center">
          <Link href="/">Hidroing</Link>
          <span className="opacity-50">/</span>
          <span>{t('crumb')}</span>
        </div>
        <h1 className="font-medium tracking-[-0.025em] leading-[1.02] text-[clamp(40px,5.4vw,88px)] text-balance m-0">
          {t('title')}
        </h1>
      </section>

      <section className="max-w-[1440px] mx-auto px-[clamp(20px,4vw,64px)] py-[clamp(56px,9vw,140px)]">
        <div className="grid grid-cols-[1.1fr_1fr] gap-20 items-start max-md:grid-cols-[1fr] max-md:gap-10">
          {/* Contact info */}
          <div className="grid gap-9">
            {infoBlocks.map((block) => (
              <div
                key={block.label}
                className="border-t border-rule pt-[18px] grid grid-cols-[140px_1fr] gap-6 items-baseline last:border-b last:border-rule last:pb-[18px]">
                <div className="font-mono text-[11px] tracking-[0.08em] uppercase text-ink-3">
                  {block.label}
                </div>
                <div className="text-[18px] tracking-[-0.01em] font-medium leading-[1.4]">
                  {block.href ? (
                    <a
                      href={block.href}
                      className="hover:text-green-ink transition-colors">
                      {block.value}
                    </a>
                  ) : (
                    block.value.split('\n').map((line, i, arr) => (
                      <span key={i}>
                        {line}
                        {i < arr.length - 1 && <br />}
                      </span>
                    ))
                  )}
                </div>
              </div>
            ))}

            {/* Map */}
            <div className="mt-12 h-[400px] relative">
              <Placeholder
                corner="OSIJEK · 45.557°N"
                label={t('mapLabel')}
                style={{ width: '100%', height: '100%' }}
              />
              <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-full flex flex-col items-center">
                <div className="px-2.5 py-1.5 bg-ink text-paper font-mono text-[11px] tracking-[0.08em] uppercase whitespace-nowrap absolute -top-8 left-1/2 -translate-x-1/2">
                  Hidroing
                </div>
                <div className="w-3.5 h-3.5 rounded-full bg-green shadow-[0_0_0_6px_rgba(255,255,255,0.9),0_2px_8px_rgba(0,0,0,0.3)]" />
                <div className="w-px h-6 bg-ink" />
              </div>
            </div>
          </div>

          {/* Enquiry form */}
          <form
            className="enquiry grid gap-[18px] p-8 border border-rule rounded-[4px] bg-white"
            onSubmit={handleSubmit}>
            <div className="font-mono text-[11px] tracking-widest uppercase text-ink-3 font-medium mb-1.5 flex items-center">
              <GreenDot />
              <span>{t('formEyebrow')}</span>
            </div>

            <div className="grid grid-cols-2 gap-3.5">
              <div className="grid gap-1.5">
                <label className="font-mono text-[11px] tracking-[0.08em] uppercase text-ink-3">
                  {t('formName')}
                </label>
                <input
                  type="text"
                  required
                  placeholder="Ivan Ivić"
                  className="px-3.5 py-3 border border-rule rounded-[3px] font-sans bg-paper text-ink transition-colors text-base"
                />
              </div>
              <div className="grid gap-1.5">
                <label className="font-mono text-[11px] tracking-[0.08em] uppercase text-ink-3">
                  {t('formOrg')}
                </label>
                <input
                  type="text"
                  placeholder="Grad / Tvrtka"
                  className="px-3.5 py-3 border border-rule rounded-[3px] font-sans bg-paper text-ink transition-colors text-base"
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-3.5">
              <div className="grid gap-1.5">
                <label className="font-mono text-[11px] tracking-[0.08em] uppercase text-ink-3">
                  {t('formEmail')}
                </label>
                <input
                  type="email"
                  required
                  placeholder="ivan@primjer.hr"
                  className="px-3.5 py-3 border border-rule rounded-[3px] font-sans bg-paper text-ink transition-colors text-base"
                />
              </div>
              <div className="grid gap-1.5">
                <label className="font-mono text-[11px] tracking-[0.08em] uppercase text-ink-3">
                  {t('formPhone')}
                </label>
                <input
                  type="tel"
                  placeholder="+385 …"
                  className="px-3.5 py-3 border border-rule rounded-[3px] font-sans bg-paper text-ink transition-colors text-base"
                />
              </div>
            </div>

            <div className="grid gap-1.5">
              <label className="font-mono text-[11px] tracking-[0.08em] uppercase text-ink-3">
                {t('formScope')}
              </label>
              <select className="px-3.5 py-3 border border-rule rounded-[3px] font-sans bg-paper text-ink transition-colors text-base">
                {scopes.map((s) => (
                  <option key={s}>{s}</option>
                ))}
              </select>
            </div>

            <div className="grid gap-1.5">
              <label className="font-mono text-[11px] tracking-[0.08em] uppercase text-ink-3">
                {t('formDesc')}
              </label>
              <textarea
                placeholder={t('formDescPlaceholder')}
                className="px-3.5 py-3 border border-rule rounded-[3px] font-sans bg-paper text-ink transition-colors text-base min-h-[120px] resize-y"
              />
            </div>

            <button
              type="submit"
              className="inline-flex items-center gap-2.5 px-[22px] py-3.5 rounded-full font-sans font-medium text-[14px] tracking-[-0.01em] border border-ink bg-ink text-paper cursor-pointer transition-all duration-150 hover:bg-green-ink hover:border-green-ink justify-self-start">
              {t('formSubmit')} <Arrow />
            </button>

            <div className="text-[12px] text-ink-4">{t('formNote')}</div>
          </form>
        </div>
      </section>
    </main>
  );
}

